import re


_JOB_PATTERN = re.compile(
    r"^JOB (?P<name>\S+) AT (?P<hour>\d{2}):(?P<minute>\d{2}) "
    r"RUN (?P<script>\S+?\.crms)"
    r"(?: ON_ERROR (?P<policy>ABORT|CONTINUE|RETRY:(?P<retries>\d+)))?$"
)


def parse_schedule(cfg_text: str) -> list[dict]:
    """Parse a Meridian CRM 4.2 batch schedule while preserving file order."""
    schedule: list[dict] = []

    for line_number, raw_line in enumerate(cfg_text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        match = _JOB_PATTERN.fullmatch(line)
        if match is None:
            raise ValueError(f"Invalid schedule line {line_number}: {raw_line!r}")

        hour = int(match.group("hour"))
        minute = int(match.group("minute"))
        if hour > 23 or minute > 59:
            raise ValueError(
                f"Invalid scheduled time on line {line_number}: "
                f"{match.group('hour')}:{match.group('minute')}"
            )

        clause = match.group("policy")
        if clause is None or clause == "ABORT":
            on_error = {"policy": "ABORT", "retries": 0}
        elif clause == "CONTINUE":
            on_error = {"policy": "CONTINUE", "retries": 0}
        else:
            on_error = {
                "policy": "RETRY",
                "retries": int(match.group("retries")),
            }

        schedule.append(
            {
                "name": match.group("name"),
                "at": f"{match.group('hour')}:{match.group('minute')}",
                "script": match.group("script"),
                "on_error": on_error,
            }
        )

    return schedule
